<?php
/**
 * Villa Azur — i18n layer for the reservation engine + its emails.
 *
 * Polylang translates page/post content, but it has no reach into hardcoded
 * PHP strings (labels, validation messages, email copy) generated by the
 * reservation module — that's what this file is for. Kept separate from
 * villa-azur-reservation.php so the pricing engine stays focused on pricing.
 *
 * Language for a given request is resolved in two different contexts:
 *   - Page render (popup UI text): pll_current_language() is accurate, since
 *     Polylang has already parsed the /en/, /de/... URL prefix.
 *   - Form submission (AJAX, for the authoritative email/entry text): the
 *     request goes through admin-ajax.php / REST, which carries no language
 *     prefix, so pll_current_language() cannot be trusted there. Instead the
 *     guest's language is captured into a hidden `vaz_lang` field (JS, at
 *     popup-open time, from the same CFG.lang the page was rendered with)
 *     and read back from the raw POST — the same technique villa-azur-fix.php
 *     already uses for the vaz_hp/vaz_ts spam-guard fields.
 */

if (!defined('ABSPATH')) {
    exit;
}

final class VAZ_I18N {

    const LANGS = ['fr', 'en', 'de', 'pl', 'ru'];
    const DEFAULT_LANG = 'fr';

    /** Resolve the language to use for the CURRENT request. */
    public static function current() {
        // Submission context: trust the guest-captured hidden field first.
        // phpcs:ignore WordPress.Security.NonceVerification.Missing -- FF verifies its own nonce upstream before these filters run.
        $raw = isset($_POST['data']) ? wp_unslash($_POST['data']) : '';
        if ($raw !== '') {
            parse_str($raw, $fields);
            if (!empty($fields['vaz_lang']) && in_array($fields['vaz_lang'], self::LANGS, true)) {
                return $fields['vaz_lang'];
            }
        }
        if (function_exists('pll_current_language')) {
            $lang = pll_current_language();
            if (in_array($lang, self::LANGS, true)) {
                return $lang;
            }
        }
        return self::DEFAULT_LANG;
    }

    /** Human-readable language name, in ITS OWN language (for a language picker). */
    public static function native_name($lang) {
        $names = [
            'fr' => 'Français', 'en' => 'English', 'de' => 'Deutsch',
            'pl' => 'Polski', 'ru' => 'Русский',
        ];
        return $names[$lang] ?? $lang;
    }

    /**
     * Slavic-aware pluralisation. $forms is either [one, other] (fr/en/de) or
     * [one, few, many] (pl/ru, standard mod10/mod100 CLDR-style rule).
     */
    public static function plural($lang, $n, array $forms) {
        $n = abs((int) $n);
        if (in_array($lang, ['pl', 'ru'], true) && count($forms) === 3) {
            $mod10  = $n % 10;
            $mod100 = $n % 100;
            if ($mod10 === 1 && $mod100 !== 11) {
                return $forms[0];
            }
            if ($mod10 >= 2 && $mod10 <= 4 && !($mod100 >= 12 && $mod100 <= 14)) {
                return $forms[1];
            }
            return $forms[2];
        }
        return $n === 1 ? $forms[0] : end($forms);
    }

    /** Word forms for countable nouns used across UI/emails. */
    const WORDS = [
        'night'  => ['fr' => ['nuit', 'nuits'], 'en' => ['night', 'nights'], 'de' => ['Nacht', 'Nächte'], 'pl' => ['noc', 'noce', 'nocy'], 'ru' => ['ночь', 'ночи', 'ночей']],
        'room'   => ['fr' => ['chambre', 'chambres'], 'en' => ['room', 'rooms'], 'de' => ['Zimmer', 'Zimmer'], 'pl' => ['pokój', 'pokoje', 'pokoi'], 'ru' => ['номер', 'номера', 'номеров']],
        'adult'  => ['fr' => ['adulte', 'adultes'], 'en' => ['adult', 'adults'], 'de' => ['Erwachsener', 'Erwachsene'], 'pl' => ['dorosły', 'dorosłych', 'dorosłych'], 'ru' => ['взрослый', 'взрослых', 'взрослых']],
        'child'  => ['fr' => ['enfant', 'enfants'], 'en' => ['child', 'children'], 'de' => ['Kind', 'Kinder'], 'pl' => ['dziecko', 'dzieci', 'dzieci'], 'ru' => ['ребёнок', 'ребёнка', 'детей']],
        'person' => ['fr' => ['personne', 'personnes'], 'en' => ['person', 'people'], 'de' => ['Person', 'Personen'], 'pl' => ['osoba', 'osoby', 'osób'], 'ru' => ['человек', 'человека', 'человек']],
    ];

    public static function word($lang, $key, $n) {
        $forms = self::WORDS[$key][$lang] ?? self::WORDS[$key][self::DEFAULT_LANG];
        return self::plural($lang, $n, $forms);
    }

    /** Month names, genitive case where the language requires it for "10 <month> 2026". */
    const MONTHS = [
        'fr' => [1 => 'janvier', 'février', 'mars', 'avril', 'mai', 'juin', 'juillet', 'août', 'septembre', 'octobre', 'novembre', 'décembre'],
        'en' => [1 => 'January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'],
        'de' => [1 => 'Januar', 'Februar', 'März', 'April', 'Mai', 'Juni', 'Juli', 'August', 'September', 'Oktober', 'November', 'Dezember'],
        'pl' => [1 => 'stycznia', 'lutego', 'marca', 'kwietnia', 'maja', 'czerwca', 'lipca', 'sierpnia', 'września', 'października', 'listopada', 'grudnia'],
        'ru' => [1 => 'января', 'февраля', 'марта', 'апреля', 'мая', 'июня', 'июля', 'августа', 'сентября', 'октября', 'ноября', 'декабря'],
    ];

    /** "10 August 2026" / "10. August 2026" (German gets the trailing period on the day). */
    public static function format_date($iso, $lang) {
        $dt = DateTime::createFromFormat('Y-m-d', $iso);
        if (!$dt) {
            return $iso;
        }
        $day   = (int) $dt->format('j');
        $month = self::MONTHS[$lang][(int) $dt->format('n')] ?? self::MONTHS[self::DEFAULT_LANG][(int) $dt->format('n')];
        $year  = $dt->format('Y');
        $dayStr = ($lang === 'de') ? $day . '.' : (string) $day;
        return "$dayStr $month $year";
    }

