            'email.client.subject' => ['fr' => 'Villa Azur — Votre demande de réservation est bien reçue', 'en' => 'Villa Azur — Your reservation request has been received', 'de' => 'Villa Azur — Ihre Reservierungsanfrage ist eingegangen', 'pl' => 'Villa Azur — Twoje zapytanie o rezerwację zostało przyjęte', 'ru' => 'Villa Azur — Ваш запрос на бронирование получен'],
            'email.client.heading'  => ['fr' => 'Merci, %s !', 'en' => 'Thank you, %s!', 'de' => 'Vielen Dank, %s!', 'pl' => 'Dziękujemy, %s!', 'ru' => 'Спасибо, %s!'],
            'email.client.intro'    => ['fr' => "Nous avons bien reçu votre demande de réservation à Villa Azur Djerba, et nous nous réjouissons déjà à l'idée de vous accueillir. Notre équipe vous contactera sous 24h pour confirmer la disponibilité et finaliser votre séjour.", 'en' => 'We have received your reservation request for Villa Azur Djerba, and we are already looking forward to welcoming you. Our team will contact you within 24 hours to confirm availability and finalise your stay.', 'de' => 'Wir haben Ihre Reservierungsanfrage für die Villa Azur Djerba erhalten und freuen uns bereits darauf, Sie bei uns willkommen zu heißen. Unser Team wird sich innerhalb von 24 Stunden bei Ihnen melden, um die Verfügbarkeit zu bestätigen und Ihren Aufenthalt zu finalisieren.', 'pl' => 'Otrzymaliśmy Państwa zapytanie o rezerwację w Villa Azur Djerba i już nie możemy się doczekać, aby Państwa gościć. Nasz zespół skontaktuje się w ciągu 24 godzin, aby potwierdzić dostępność i sfinalizować szczegóły pobytu.', 'ru' => 'Мы получили ваш запрос на бронирование в Villa Azur Djerba и уже рады возможности принять вас у себя. Наша команда свяжется с вами в течение 24 часов, чтобы подтвердить наличие мест и завершить оформление вашего пребывания.'],
            'email.client.footer'   => ['fr' => 'Villa Azur Djerba — Plage de Sidi Mehrez<br>Tél / WhatsApp : +216 75 757 257 &middot; villa_azur@yahoo.fr', 'en' => 'Villa Azur Djerba — Sidi Mehrez Beach<br>Phone / WhatsApp: +216 75 757 257 &middot; villa_azur@yahoo.fr', 'de' => 'Villa Azur Djerba — Strand von Sidi Mehrez<br>Tel. / WhatsApp: +216 75 757 257 &middot; villa_azur@yahoo.fr', 'pl' => 'Villa Azur Djerba — Plaża Sidi Mehrez<br>Tel. / WhatsApp: +216 75 757 257 &middot; villa_azur@yahoo.fr', 'ru' => 'Villa Azur Djerba — Пляж Сиди-Мехрез<br>Тел. / WhatsApp: +216 75 757 257 &middot; villa_azur@yahoo.fr'],

            // ── Welcome block (email_welcome_html) ───────────────────────────
            'email.welcome.p1' => ['fr' => "Villa Azur est bien plus qu'un hôtel : c'est une maison de famille où l'hospitalité est une tradition. Avec seulement 16 chambres ouvertes sur la Méditerranée, nous vous préparons un accueil intime et chaleureux, à l'image de l'art de vivre djerbien — là où la mer rencontre la sérénité.", 'en' => 'Villa Azur is far more than a hotel: it is a family home where hospitality is a tradition. With only 16 rooms open to the Mediterranean, we are preparing an intimate, warm welcome for you, true to the Djerbian art of living — where the sea meets serenity.', 'de' => 'Villa Azur ist weit mehr als ein Hotel: Es ist ein Familienhaus, in dem Gastfreundschaft Tradition hat. Mit nur 16 Zimmern zum Mittelmeer bereiten wir Ihnen einen persönlichen, herzlichen Empfang, ganz im Sinne der djerbischen Lebenskunst — dort, wo das Meer auf Gelassenheit trifft.', 'pl' => 'Villa Azur to znacznie więcej niż hotel: to rodzinny dom, w którym gościnność jest tradycją. Mając zaledwie 16 pokoi otwartych na Morze Śródziemne, przygotowujemy dla Państwa kameralne i ciepłe przyjęcie, w duchu dżerbańskiej sztuki życia — tam, gdzie morze spotyka się ze spokojem.', 'ru' => 'Villa Azur — это гораздо больше, чем отель: это семейный дом, где гостеприимство является традицией. Имея всего 16 номеров с видом на Средиземное море, мы готовим для вас тёплый, душевный приём в духе джербийского искусства жить — там, где море встречается со спокойствием.'],
            'email.welcome.p2' => ['fr' => "Toute l'équipe se réjouit déjà à l'idée de vous accueillir sur la plage de Sidi Mehrez. En attendant notre confirmation sous 24h, n'hésitez pas à nous écrire si la moindre question se présente — nous sommes là pour que votre séjour commence dans les meilleures conditions, avant même votre arrivée.", 'en' => 'Our whole team is already looking forward to welcoming you on Sidi Mehrez beach. While you wait for our confirmation within 24 hours, please do not hesitate to write to us with any question at all — we are here to make sure your stay starts under the best conditions, even before you arrive.', 'de' => 'Unser gesamtes Team freut sich bereits darauf, Sie am Strand von Sidi Mehrez willkommen zu heißen. Während Sie auf unsere Bestätigung innerhalb von 24 Stunden warten, zögern Sie bitte nicht, uns bei der kleinsten Frage zu schreiben — wir sind für Sie da, damit Ihr Aufenthalt schon vor Ihrer Ankunft unter den besten Voraussetzungen beginnt.', 'pl' => 'Cały nasz zespół z niecierpliwością czeka, aby powitać Państwa na plaży Sidi Mehrez. Oczekując na nasze potwierdzenie w ciągu 24 godzin, prosimy śmiało pisać do nas z każdym, nawet najmniejszym pytaniem — jesteśmy tu po to, aby Państwa pobyt rozpoczął się w jak najlepszych warunkach, jeszcze przed przyjazdem.', 'ru' => 'Вся наша команда уже с нетерпением ждёт возможности принять вас на пляже Сиди-Мехрез. Пока вы ожидаете нашего подтверждения в течение 24 часов, пожалуйста, не стесняйтесь писать нам по любому вопросу — мы здесь для того, чтобы ваше пребывание началось на самых лучших условиях ещё до вашего приезда.'],
            'email.welcome.sig' => ['fr' => "— L'équipe Villa Azur, Djerba", 'en' => '— The Villa Azur team, Djerba', 'de' => '— Das Villa-Azur-Team, Djerba', 'pl' => '— Zespół Villa Azur, Dżerba', 'ru' => '— Команда Villa Azur, Джерба'],

